function onTheory(root){
  const w=root.querySelector('#w-map');
  if(w){const xp=Object.keys(XP).map(k=>({k,name:XP[k].name,short:XP[k].name.replace('гора ','').replace('остров ','о. ').replace('мыс ',''),lo:XP[k].lo,la:XP[k].la,info:`${XP[k].dir[0].toUpperCase()+XP[k].dir.slice(1)} крайняя точка, ${XP[k].c}. ${XP[k].info}`,c:k.length>1?'var(--accent-ink)':'var(--bad)',dx:{N:0,NI:7,S:0,W:4,E:-6,EI:-6}[k],dy:{N:-9,NI:4,S:15,W:15,E:-9,EI:14}[k],a:{N:'middle',S:'middle',E:'end',EI:'end'}[k]}));
    mapWidget(w,{title:'Карта-тренажёр: нажми на точку или сыграй «Найди на карте»',hint:'Нажми на точку — узнаешь, что это. Кнопка «🎯» — игра: найди названный объект.',labels:false,
     views:{'Вся Россия':null,'Запад и Кавказ':{box:[18,39.5,52,62]},'Восток':{box:[125,40,192,70]}},
     modes:{'Крайние точки':xp,'Соседи':NB.map(n=>({k:n.k,name:n.name,lo:n.lo,la:n.la,info:n.km?`Граница с Россией ≈ ${N(n.km)} км.`:'Сухопутный сосед на юго-западе.'})).concat([{k:'usa',name:'США (только морская граница)',lo:191.4,la:64.6,info:'Граница по Берингову проливу.',c:'var(--accent-ink)'},{k:'jpn',name:'Япония (только морская граница)',lo:142.8,la:43.6,info:'Граница по проливам Лаперуза и Кунаширскому.',c:'var(--accent-ink)'}]),
      'Моря':SEAS.map(s=>({k:s.k,name:s.name,lo:s.lo,la:s.la,info:`Бассейн: ${s.o}${s.o.indexOf('бессточ')<0?' океан':''}.`,c:'var(--accent-ink)'})),
      'Объекты':OBJ.map(o=>Object.assign({c:'var(--ok)'},o))}});}
  const z=root.querySelector('#w-tz');
  if(z){const opt=c=>`<option value="${c}">${c} (${mskS(c)})</option>`;
    z.innerHTML=`<b>Часовые зоны: выбери два города</b>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0"><select id="tzA">${TZN.map(opt).join('')}</select><select id="tzB">${TZN.map(opt).join('')}</select></div>
    <label>Время в первом городе: <output id="tzo"></output><input type="range" id="tzH" min="0" max="23" step="1" value="12"></label>
    <div id="tzpic" class="fig" style="flex-direction:column;align-items:center"></div><div id="tzt" style="text-align:center;line-height:1.7"></div>`;
    const g=id=>z.querySelector('#'+id);g('tzA').value='Москва';g('tzB').value='Владивосток';
    const u=()=>{const a=g('tzA').value,b=g('tzB').value,h=+g('tzH').value;g('tzo').textContent=hh(h);const d=TZC[b]-TZC[a];const raw=h+d,t=((raw%24)+24)%24;
      let s='';for(let i=-1;i<=9;i++){const x=6+(i+1)*29.8;const on=i===TZC[a]||i===TZC[b];s+=RC(x,8,28,26,{f:on?'var(--hl)':'var(--accent)',fo:on?0.85:0.15,rx:4})+TX(x+14,25,i===0?'МСК':(i>0?'+':'−')+Math.abs(i),{fs:10.5});}
      s+=TX(6+(TZC[a]+1)*29.8+14,48,'A',{fs:12,c:'var(--bad)'})+TX(6+(TZC[b]+1)*29.8+14,48+(TZC[a]===TZC[b]?14:0),'B',{fs:12,c:'var(--bad)'});
      const mp=mapSVG({wd:520,pad:true,layer:(P,k)=>[a,b].map((c,i)=>{const [x,y]=P(...GEO.PT[c]);return CI(x,y,4,{f:'var(--bad)',s:'var(--card)'})+TX(x,y-7,(i?'B: ':'A: ')+(i?hh(t):hh(h)),{fs:11,c:'var(--ink)'});}).join('')});
      g('tzpic').innerHTML=SV(340,56,s,'Часовые зоны России',520)+mp;
      g('tzt').innerHTML=`${a}: ${utcS(a)}, ${b}: ${utcS(b)} → разница <span class="out">${d>0?'+':d<0?'−':''}${Math.abs(d)} ч</span><br>${a}: ${hh(h)} → ${b}: <span class="out">${hh(t)}</span>${raw>=24?' следующего дня':raw<0?' предыдущего дня':''}`;};
    ['tzA','tzB','tzH'].forEach(id=>g(id).oninput=u);u();}
}
